#include <gtest/gtest.h>
#include "mobile_robot_hardware/protocol.hpp"
namespace protocol=mobile_robot_hardware::protocol;
TEST(Protocol,ConfigureRoundTrip){const protocol::ConfigurePayload p{2048.0F};const auto frame=protocol::encode_frame(protocol::MessageType::kCommandConfigure,42U,p);const auto d=protocol::decode_frame(frame);ASSERT_TRUE(d.has_value());EXPECT_EQ(d->header.sequence,42U);protocol::ConfigurePayload out{};ASSERT_TRUE(protocol::decode_payload(*d,out));EXPECT_FLOAT_EQ(out.ticks_per_revolution,2048.0F);} TEST(Protocol,RejectsCorruptedCrc){protocol::EnablePayload p{1U};auto frame=protocol::encode_frame(protocol::MessageType::kCommandEnable,7U,p);frame[sizeof(protocol::Header)]^=0x01U;EXPECT_FALSE(protocol::decode_frame(frame).has_value());} TEST(Protocol,AckRoundTrip){const protocol::AckPayload p{static_cast<uint8_t>(protocol::MessageType::kCommandConfigure),static_cast<uint8_t>(protocol::AckStatus::kAccepted)};const auto frame=protocol::encode_frame(protocol::MessageType::kAck,99U,p);const auto d=protocol::decode_frame(frame);ASSERT_TRUE(d.has_value());protocol::AckPayload ack{};ASSERT_TRUE(protocol::decode_payload(*d,ack));EXPECT_EQ(ack.command_type,static_cast<uint8_t>(protocol::MessageType::kCommandConfigure));EXPECT_EQ(ack.status,static_cast<uint8_t>(protocol::AckStatus::kAccepted));}
